import{_ as a,o as e,c as r,a4 as d}from"./chunks/framework.BybBnFXO.js";const _=JSON.parse('{"title":"花式切工","description":"","frontmatter":{"title":"花式切工","cutting":"fancy-cuts"},"headers":[],"relativePath":"zh/cutting/fancy-cuts.md","filePath":"zh/cutting/fancy-cuts.md","lastUpdated":1785925441000}'),i={name:"zh/cutting/fancy-cuts.md"};function n(l,t,o,c,s,h){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="花式切工" tabindex="-1">花式切工 <a class="header-anchor" href="#花式切工" aria-label="Permalink to &quot;花式切工&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>除圆明亮式外的所有切工统称花式切工——公主方、祖母绿切、梨形、 椭圆形、马眼形、心形、祖母绿阶梯切等。每种依原石形状、内含物 位置与审美偏好而选。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>公主方 (princess)：方形，保留圆明亮火彩，现代婚戒主流。</li><li>祖母绿切 (emerald)：阶梯式刻面，突出净度——适合高净度大石。</li><li>梨形/马眼/心形：异形轮廓，需冠亭比例对称避免&quot;蝴蝶结效应&quot;。</li><li>花式切工按尺寸定价时单克拉价常低于圆明亮（切工损耗与需求差异）。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>diamond</td><td>Emerald step cut</td><td>—</td></tr><tr><td>diamond</td><td>Princess</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',8)])])}const m=a(i,[["render",n]]);export{_ as __pageData,m as default};
